-- Terminal rooms for the Viewer (v3: recompiled 2026-07-15, closes the coordinate-offset
-- island bug found via ROOM_LENS_VISUAL_HIGHLIGHT_SPEC.md's fleet connectivity survey --
-- the v2 patch's compiled rooms sat ~(543,51)m offset from the real door/wall geometry,
-- an artifact of a stale extraction snapshot at compile time, not a coordinate BUG in
-- compile_rooms.py itself -- rerunning it against the CURRENT Terminal_extracted.db
-- reproduces correctly-positioned rooms (verified: room x/y range now matches real door
-- x/y range almost exactly). Same compile_rooms.py, same rules, fresh run, no manual edits.
-- Self-heal patch (ROOM_TAXONOMY_STRATEGY_2026-07-12.md Lane A rules: R-MERGE + R-REJECT,
-- compile_rooms.py). Idempotent: owns only RM_*/STC_* compiled rows.
DROP TABLE IF EXISTS spatial_structure;
CREATE TABLE spatial_structure (guid TEXT, type TEXT, name TEXT, parent_guid TEXT,
  object_type TEXT, predefined_type TEXT, center_x REAL, center_y REAL, center_z REAL,
  size_x REAL, size_y REAL, size_z REAL, room_guid TEXT);
CREATE TABLE IF NOT EXISTS rel_contained_in_space (space_guid TEXT, element_guid TEXT);
DELETE FROM rel_contained_in_space WHERE space_guid LIKE 'RM_%';
